Q: Prevent concurrent access to the same data in Dart A: <p>You can use <code>AsyncCache</code>.</p>
<pre class="lang-dart prettyprint-override"><code>void main() async {
  final sw = Stopwatch()..start();
  const url = 'some url';
  for (var i = 0; i &lt; 5; i++) {
    final image = await _cache[url];
    _info(sw, image);
  }

  print('Remove $url');
  _cache.remove(url);

  for (var i = 0; i &lt; 5; i++) {
    final image = await _cache[url];
    _info(sw, image);
  }
}

void _info(Stopwatch sw, String text) {
  sw.stop();
  print('${sw.elapsedMilliseconds} ms: $text');
  sw.reset();
  sw.start();
}

final _cache = AsyncCache(_getImage);

Future&lt;String&gt; _getImage(String url) async {
  await Future&lt;void&gt;.delayed(Duration(milliseconds: 1000));
  return 'Image: $url';
}

class AsyncCache&lt;K, V&gt; {
  final Future&lt;V&gt; Function(K) _valueFactory;

  final Map&lt;K, Future&lt;V&gt;&gt; _map = {};

  AsyncCache(Future&lt;V&gt; Function(K) valueFactory) : _valueFactory = valueFactory;

  Future&lt;V&gt; operator [](K key) {
    final value = _map[key];
    if (value != null) {
      return value;
    }

    final newValue = _valueFactory(key);
    _map[key] = newValue;
    return newValue;
  }

  void clear() =&gt; _map.clear();

  void remove(K key) =&gt; _map.remove(key);
}

</code></pre>
